package com.trampolim.api.hub;
import java.util.*;import java.time.*;
import static com.trampolim.api.hub.HubRules.*;import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.radar.*;import com.trampolim.api.company.CompanyRadarController;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.web.multipart.MultipartFile;
@Service
@ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class HubService {
 private final JdbcTemplate jdbc;private final RadarBridge bridge;private final HubAccess access;private final HubLogoStore logos;private final TransactionTemplate tx;
 public HubService(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,RadarBridge bridge,HubAccess access,HubLogoStore logos,@Qualifier("empresasTransactionManager")PlatformTransactionManager manager){this.jdbc=jdbc;this.bridge=bridge;this.access=access;this.logos=logos;tx=new TransactionTemplate(manager);}
 public void exists(long id){if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM enterprise_organizations WHERE id=? AND organization_type='ASSOCIATION')",Boolean.class,id)))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Associação não encontrada.");}
 public void audit(long id,String actor,String event){jdbc.update("INSERT INTO enterprise_organization_audit_events(organization_id,actor_email,event_type,entity_type,entity_reference) VALUES (?,?,?,'HUB',?)",id,actor,event,Long.toString(id));}
 public Map<String,Object> profile(long id){exists(id);var row=jdbc.queryForMap("SELECT o.name,o.status,p.legal_name,p.legal_identifier,p.contact_email,p.contact_phone,p.responsible_name,p.public_slug,p.headline,p.about,p.accent_color,p.published,p.revision,(p.logo_key IS NOT NULL) AS has_logo FROM enterprise_organizations o JOIN hub_profiles p ON p.organization_id=o.id WHERE o.id=?",id);return row;}
 public Map<String,Object> saveProfile(long id,String actor,Profile body){exists(id);var p=HubRules.profile(body);return tx.execute(status->{jdbc.queryForObject("SELECT id FROM enterprise_organizations WHERE id=? FOR UPDATE",Long.class,id);jdbc.update("INSERT INTO hub_profiles(organization_id) VALUES (?) ON CONFLICT DO NOTHING",id);if(!p.institutionName().isEmpty())jdbc.update("UPDATE enterprise_organizations SET name=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",p.institutionName(),id);int changed=jdbc.update("UPDATE hub_profiles SET legal_name=?,legal_identifier=?,contact_email=?,contact_phone=?,responsible_name=?,public_slug=?,headline=?,about=?,accent_color=?,published=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND revision=?",p.legalName(),p.legalIdentifier(),p.contactEmail(),p.contactPhone(),p.responsibleName(),p.publicSlug().isEmpty()?null:p.publicSlug(),p.headline(),p.about(),p.accentColor(),p.published(),id,p.revision());if(changed==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"O perfil mudou. Atualize antes de salvar.");audit(id,actor,"HUB_PROFILE_UPDATED");return profile(id);});}
 public Map<String,Object> saveLogo(long id,String actor,MultipartFile file){exists(id);String key=logos.save(id,file);try{String old=tx.execute(status->{jdbc.queryForObject("SELECT id FROM enterprise_organizations WHERE id=? FOR UPDATE",Long.class,id);jdbc.update("INSERT INTO hub_profiles(organization_id) VALUES (?) ON CONFLICT DO NOTHING",id);String previous=jdbc.queryForObject("SELECT logo_key FROM hub_profiles WHERE organization_id=?",String.class,id);jdbc.update("UPDATE hub_profiles SET logo_key=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE organization_id=?",key,id);audit(id,actor,"HUB_LOGO_UPDATED");return previous;});logos.remove(id,old);return profile(id);}catch(RuntimeException error){logos.remove(id,key);throw error;}}
 public byte[] logo(long id){return logos.read(id,jdbc.queryForObject("SELECT logo_key FROM hub_profiles WHERE organization_id=?",String.class,id));}
 public Map<String,Object> usage(long id){exists(id);var counts=jdbc.queryForMap("SELECT (SELECT count(*) FROM enterprise_organization_companies WHERE organization_id=? AND relationship_type='ASSOCIATION_MEMBER' AND status<>'ENDED') AS companies,(SELECT count(DISTINCT LOWER(email)) FROM enterprise_organization_members WHERE organization_id=?) AS members,(SELECT count(*) FROM hub_programs WHERE organization_id=? AND status<>'ARCHIVED') AS programs,(SELECT count(*) FROM hub_campaigns WHERE organization_id=? AND status<>'ARCHIVED') AS campaigns",id,id,id,id);var active=jdbc.queryForList("SELECT p.name,p.company_limit,p.program_limit,p.member_limit,p.campaign_limit FROM hub_contracts c JOIN hub_institutional_plans p ON p.id=c.plan_id WHERE c.organization_id=? AND c.status='ACTIVE' AND CURRENT_DATE BETWEEN c.starts_on AND c.ends_on ORDER BY c.id DESC LIMIT 1",id);return Map.of("usage",counts,"limits",active.isEmpty()?Map.of("company_limit",500,"program_limit",100,"member_limit",200,"campaign_limit",30):active.get(0),"billingNotice","Licenças são registros administrativos de contrato. Não há cobrança recorrente configurada; os preços das vagas de estágio permanecem no fluxo existente.");}
 public List<Map<String,Object>> contracts(long id){return jdbc.queryForList("SELECT c.id,c.plan_id,p.name AS plan_name,p.billing_period,c.contract_reference,c.starts_on,c.ends_on,c.status,c.revision,c.created_at FROM hub_contracts c JOIN hub_institutional_plans p ON p.id=c.plan_id WHERE c.organization_id=? ORDER BY c.id DESC LIMIT 50",id);}
 public List<Map<String,Object>> plans(){return jdbc.queryForList("SELECT * FROM hub_institutional_plans ORDER BY id DESC LIMIT 100");}
 public void auditPlan(long id,String actor,String event){jdbc.update("INSERT INTO enterprise_organization_audit_events(actor_email,event_type,entity_type,entity_reference) VALUES (?,?,'HUB_PLAN',?)",actor,event,Long.toString(id));}
 public Map<String,Object> plan(String actor,Plan p){if(p==null||!text(p.code(),60).matches("[a-z0-9-]{2,60}")||text(p.name(),120).isEmpty()||!Set.of("MONTHLY","ANNUAL","LICENSE").contains(Objects.toString(p.billingPeriod(),""))||!Set.of("DRAFT","ACTIVE","ARCHIVED").contains(Objects.toString(p.status(),""))||p.companyLimit()<1||p.companyLimit()>10000||p.programLimit()<1||p.programLimit()>200||p.memberLimit()<1||p.memberLimit()>2000||p.campaignLimit()<1||p.campaignLimit()>200)bad("Revise o plano e seus limites. Nenhum preço será definido.");long id=jdbc.queryForObject("INSERT INTO hub_institutional_plans(code,name,billing_period,company_limit,program_limit,member_limit,campaign_limit,status) VALUES (?,?,?,?,?,?,?,?) RETURNING id",Long.class,p.code(),p.name(),p.billingPeriod(),p.companyLimit(),p.programLimit(),p.memberLimit(),p.campaignLimit(),p.status());auditPlan(id,actor,"HUB_PLAN_CREATED");return Map.of("id",id);}
 public Map<String,Object> contract(long org,long contractId,String actor,Contract c){exists(org);if(c==null||c.planId()<1||text(c.reference(),180).isEmpty()||!Set.of("DRAFT","ACTIVE","SUSPENDED","ENDED").contains(Objects.toString(c.status(),"")))bad("Informe plano, referência de contrato e situação.");dates(c.startsOn(),c.endsOn());if(c.status().equals("ACTIVE")&&!c.confirmedAgreement())bad("Confirme a existência de contrato autorizado. Esta operação não representa pagamento.");return tx.execute(status->{jdbc.queryForObject("SELECT id FROM enterprise_organizations WHERE id=? FOR UPDATE",Long.class,org);var plan=jdbc.queryForList("SELECT * FROM hub_institutional_plans WHERE id=? AND (status='ACTIVE' OR ?='ENDED')",c.planId(),c.status());if(plan.isEmpty())bad("Escolha um plano institucional ativo.");long id;if(contractId==0)id=jdbc.queryForObject("INSERT INTO hub_contracts(organization_id,plan_id,contract_reference,starts_on,ends_on,status) VALUES (?,?,?,?,?,?) RETURNING id",Long.class,org,c.planId(),c.reference(),LocalDate.parse(c.startsOn()),LocalDate.parse(c.endsOn()),c.status());else{int updated=jdbc.update("UPDATE hub_contracts SET plan_id=?,contract_reference=?,starts_on=?,ends_on=?,status=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=? AND revision=?",c.planId(),c.reference(),LocalDate.parse(c.startsOn()),LocalDate.parse(c.endsOn()),c.status(),contractId,org,c.revision());if(updated==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Contrato não encontrado neste ambiente ou revisão desatualizada.");id=contractId;}audit(org,actor,"HUB_CONTRACT_RECORDED");return Map.of("id",id,"paymentRecorded",false);});}
 public Map<String,Object> programs(long org,long before,int limit){page(before,limit);var rows=jdbc.queryForList("SELECT p.* FROM hub_programs p WHERE organization_id=? AND id<? ORDER BY id DESC LIMIT ?",org,before,limit+1);return pageResult(rows,limit);}
 public Map<String,Object> program(long org,long id){var row=jdbc.queryForList("SELECT * FROM hub_programs WHERE id=? AND organization_id=?",id,org).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));row.put("courses",jdbc.queryForList("SELECT course_id,title FROM hub_program_courses WHERE program_id=? ORDER BY course_id",id));return row;}
 public Map<String,Object> saveProgram(long org,long id,String actor,Program p){if(p==null||text(p.title(),180).isEmpty()||text(p.description(),4000).isEmpty())bad("Informe título e descrição do programa.");dates(p.startsOn(),p.endsOn());state(p.status());courses(p.courseIds());if(p.status().equals("PUBLISHED")&&p.courseIds().isEmpty())bad("Associe ao menos um curso publicado antes de divulgar o programa.");Map<Long,String> titles=new HashMap<>();for(Long cid:p.courseIds()){if(id>0&&p.status().equals("ARCHIVED")){var previous=jdbc.queryForList("SELECT c.title FROM hub_program_courses c JOIN hub_programs p ON p.id=c.program_id WHERE p.organization_id=? AND p.id=? AND c.course_id=?",String.class,org,id,cid);if(!previous.isEmpty())titles.put(cid,previous.get(0));}else{var course=bridge.get("/public/capacita/hub/courses/"+cid);titles.put(cid,course.path("title").asText());}}return tx.execute(status->{jdbc.queryForObject("SELECT id FROM enterprise_organizations WHERE id=? FOR UPDATE",Long.class,org);long saved=id;if(id==0)saved=jdbc.queryForObject("INSERT INTO hub_programs(organization_id,title,description,starts_on,ends_on,status) VALUES (?,?,?,?,?,?) RETURNING id",Long.class,org,p.title().trim(),p.description().trim(),LocalDate.parse(p.startsOn()),LocalDate.parse(p.endsOn()),p.status());else if(jdbc.update("UPDATE hub_programs SET title=?,description=?,starts_on=?,ends_on=?,status=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=? AND revision=?",p.title().trim(),p.description().trim(),LocalDate.parse(p.startsOn()),LocalDate.parse(p.endsOn()),p.status(),org,id,p.revision())==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Programa não encontrado nesta associação ou revisão desatualizada.");jdbc.update("DELETE FROM hub_program_courses WHERE program_id=?",saved);for(var course:titles.entrySet())jdbc.update("INSERT INTO hub_program_courses(program_id,course_id,title) VALUES (?,?,?)",saved,course.getKey(),text(course.getValue(),180));audit(org,actor,"HUB_PROGRAM_UPDATED");return program(org,saved);});}
 public Map<String,Object> campaigns(long org,long before,int limit){page(before,limit);return pageResult(jdbc.queryForList("SELECT * FROM hub_campaigns WHERE organization_id=? AND id<? ORDER BY id DESC LIMIT ?",org,before,limit+1),limit);}
 public Map<String,Object> campaign(long org,long id,String actor,Campaign p){if(p==null||text(p.title(),180).isEmpty()||text(p.body(),3000).isEmpty())bad("Informe título e texto da campanha.");dates(p.startsOn(),p.endsOn());state(p.status());return tx.execute(status->{long saved=id;if(id==0)saved=jdbc.queryForObject("INSERT INTO hub_campaigns(organization_id,title,body,starts_on,ends_on,status) VALUES (?,?,?,?,?,?) RETURNING id",Long.class,org,p.title().trim(),p.body().trim(),LocalDate.parse(p.startsOn()),LocalDate.parse(p.endsOn()),p.status());else if(jdbc.update("UPDATE hub_campaigns SET title=?,body=?,starts_on=?,ends_on=?,status=?,revision=revision+1 WHERE organization_id=? AND id=? AND revision=?",p.title().trim(),p.body().trim(),LocalDate.parse(p.startsOn()),LocalDate.parse(p.endsOn()),p.status(),org,id,p.revision())==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Campanha não encontrada nesta associação ou revisão desatualizada.");audit(org,actor,"HUB_CAMPAIGN_UPDATED");return Map.of("id",saved);});}
 public Map<String,Object> companies(long org,long before,int limit){page(before,limit);return pageResult(jdbc.queryForList("SELECT c.id,c.trade_name,c.city,c.state,c.industry,r.status,r.created_at FROM enterprise_organization_companies r JOIN companies c ON c.id=r.company_id WHERE r.organization_id=? AND r.relationship_type='ASSOCIATION_MEMBER' AND c.id<? ORDER BY c.id DESC LIMIT ?",org,before,limit+1),limit);}
 public Map<String,Object> publicOrganizations(String q,long before,int limit){page(before,limit);text(q,120);return pageResult(jdbc.queryForList("SELECT o.id,o.name,p.public_slug,p.headline,p.accent_color,(p.logo_key IS NOT NULL) AS has_logo FROM enterprise_organizations o JOIN hub_profiles p ON p.organization_id=o.id WHERE o.id<? AND o.organization_type='ASSOCIATION' AND o.status='ACTIVE' AND p.published=TRUE AND (?='' OR o.name ILIKE ?) ORDER BY o.id DESC LIMIT ?",before,q,"%"+q+"%",limit+1),limit);}
 public Map<String,Object> publicOrganization(long id){return jdbc.queryForList("SELECT o.id,o.name,p.public_slug,p.headline,p.about,p.contact_email,p.contact_phone,p.accent_color,(p.logo_key IS NOT NULL) AS has_logo FROM enterprise_organizations o JOIN hub_profiles p ON p.organization_id=o.id WHERE o.id=? AND o.organization_type='ASSOCIATION' AND o.status='ACTIVE' AND p.published=TRUE",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Página institucional indisponível."));}
 public Map<String,Object> publicPage(String slug){Long id=jdbc.query("SELECT organization_id FROM hub_profiles WHERE public_slug=?",(rs,n)->rs.getLong(1),slug).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var page=new LinkedHashMap<>(publicOrganization(id));page.put("programs",jdbc.queryForList("SELECT id,title,description,starts_on,ends_on FROM hub_programs WHERE organization_id=? AND status='PUBLISHED' AND ends_on>=CURRENT_DATE ORDER BY id DESC LIMIT 20",id));page.put("campaigns",jdbc.queryForList("SELECT id,title,body,starts_on,ends_on FROM hub_campaigns WHERE organization_id=? AND status='PUBLISHED' AND CURRENT_DATE BETWEEN starts_on AND ends_on ORDER BY id DESC LIMIT 20",id));return page;}
 public Map<String,Object> publicPrograms(long before,int limit){page(before,limit);return pageResult(jdbc.queryForList("SELECT p.id,p.organization_id,p.title,p.description,p.starts_on,p.ends_on,o.name AS institution_name FROM hub_programs p JOIN enterprise_organizations o ON o.id=p.organization_id JOIN hub_profiles h ON h.organization_id=o.id WHERE p.id<? AND p.status='PUBLISHED' AND p.ends_on>=CURRENT_DATE AND o.status='ACTIVE' AND o.organization_type='ASSOCIATION' AND h.published=TRUE ORDER BY p.id DESC LIMIT ?",before,limit+1),limit);}
 public Map<String,Object> publicProgram(long id){var row=jdbc.queryForList("SELECT p.id,p.organization_id,p.title,p.description,p.starts_on,p.ends_on,o.name AS institution_name FROM hub_programs p JOIN enterprise_organizations o ON o.id=p.organization_id JOIN hub_profiles h ON h.organization_id=o.id WHERE p.id=? AND p.status='PUBLISHED' AND p.ends_on>=CURRENT_DATE AND o.status='ACTIVE' AND h.published=TRUE",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Programa indisponível."));row.put("courses",jdbc.queryForList("SELECT course_id,title FROM hub_program_courses WHERE program_id=? ORDER BY course_id",id));return row;}
 public Map<String,Object> dashboard(long org,String from,String to,Long company){dates(from,to);if(company!=null&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM enterprise_organization_companies WHERE organization_id=? AND company_id=? AND relationship_type='ASSOCIATION_MEMBER' AND status='ACTIVE')",Boolean.class,org,company)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Empresa fora do escopo desta associação.");String linked=" EXISTS(SELECT 1 FROM enterprise_organization_companies r WHERE r.organization_id=? AND r.company_id=c.id AND r.relationship_type='ASSOCIATION_MEMBER' AND r.status='ACTIVE') AND (?::bigint IS NULL OR c.id=?)";Object[] scope={org,company,company};var out=new LinkedHashMap<String,Object>();out.put("companies",jdbc.queryForObject("SELECT count(*) FROM companies c WHERE "+linked,Long.class,scope));var args=new ArrayList<Object>(Arrays.asList(scope));args.add(LocalDate.parse(from));args.add(LocalDate.parse(to).plusDays(1));String jobs=" FROM company_listings l JOIN companies c ON c.id=l.company_id WHERE "+linked+" AND "+CompanyRadarController.PUBLIC_JOB_CONDITION+" AND l.created_at>=? AND l.created_at<?";out.put("openVacancies",jdbc.queryForObject("SELECT count(*)"+jobs,Long.class,args.toArray()));String future=" FROM company_future_demands d JOIN companies c ON c.id=d.company_id WHERE "+linked+" AND c.verification_status='APPROVED' AND d.status='PUBLISHED' AND d.hiring_end>=CURRENT_DATE AND d.created_at>=? AND d.created_at<?";out.put("futureDemands",jdbc.queryForObject("SELECT count(*)"+future,Long.class,args.toArray()));out.put("estimatedHires",jdbc.queryForObject("SELECT COALESCE(sum(d.estimated_hires),0)"+future,Long.class,args.toArray()));out.put("occupations",jdbc.queryForList("SELECT d.occupation,count(*) AS demands"+future+" GROUP BY d.occupation ORDER BY count(*) DESC,d.occupation LIMIT 20",args.toArray()));out.put("skills",jdbc.queryForList("SELECT x->>'skillCode' AS skill_code,count(*) AS demands"+future.replaceFirst(" WHERE "," CROSS JOIN LATERAL jsonb_array_elements(d.requirements->'skills') x WHERE ")+" GROUP BY x->>'skillCode' ORDER BY count(*) DESC,skill_code LIMIT 40",args.toArray()));var demands=jdbc.queryForList("SELECT d.id,(d.requirements->>'revision')::int AS revision"+future+" ORDER BY d.id DESC LIMIT 200",args.toArray());List<DemandScope> ids=demands.stream().map(row->new DemandScope(((Number)row.get("id")).longValue(),((Number)row.get("revision")).intValue())).toList();try{out.put("candidates",bridge.convert(bridge.post("/integrations/hub/candidates",new CandidateQuery(org,ids,from,to)),Map.class));}catch(ResponseStatusException error){out.put("candidates",Map.of("status","UNAVAILABLE"));}out.put("candidateCoverage",Map.of("examinedDemands",ids.size(),"partial",((Number)out.get("futureDemands")).longValue()>ids.size()));var programs=jdbc.queryForList("SELECT id FROM hub_programs WHERE organization_id=? AND status='PUBLISHED' ORDER BY id DESC LIMIT 200",org);List<ProgramScope> programIds=new ArrayList<>();var allCourses=jdbc.queryForList("SELECT c.program_id,c.course_id FROM hub_program_courses c JOIN hub_programs p ON p.id=c.program_id WHERE p.organization_id=? AND p.status='PUBLISHED'",org);for(var item:programs){long pid=((Number)item.get("id")).longValue();programIds.add(new ProgramScope(pid,allCourses.stream().filter(c->((Number)c.get("program_id")).longValue()==pid).map(c->((Number)c.get("course_id")).longValue()).toList()));}out.put("programs",jdbc.queryForObject("SELECT count(*) FROM hub_programs WHERE organization_id=? AND status<>'ARCHIVED'",Long.class,org));try{out.put("learning",bridge.convert(bridge.post("/integrations/hub/learning",new LearningQuery(org,programIds,from,to)),Map.class));}catch(ResponseStatusException error){out.put("learning",Map.of("status","UNAVAILABLE"));}out.put("confirmedHires",null);out.put("notice","Dados das empresas ativamente vinculadas. Previsões são estimativas; participantes exigem consentimento institucional. Período filtra criação das vagas/previsões e adesão dos participantes. Conclusões retratam a situação atual dessa coorte. Contratações confirmadas não possuem fonte disponível.");out.put("from",from);out.put("to",to);return out;}
 public static Map<String,Object> pageResult(List<Map<String,Object>> rows,int limit){var page=new LinkedHashMap<String,Object>();page.put("items",rows.stream().limit(limit).toList());page.put("nextCursor",rows.size()>limit?rows.get(limit-1).get("id"):null);return page;}
}
